

import React, { useRef, useEffect } from 'react';
// @ts-ignore
import gsap from 'gsap';
// @ts-ignore
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import './HorizontalScrollServices.css';
import websiteDesignImg from '../assets/websitedesign.png';
import mediaSocialDesignImg from '../assets/mediasocialdesign.png';
import brandDevelopmentImg from '../assets/branddevelopment.png';
import photographyImg from '../assets/photography.png';

gsap.registerPlugin(ScrollTrigger);

const slides = [
  {
    key: 'website',
    bg: websiteDesignImg,
    title: 'Website Design',
    subtitle: '網站設計',
  },
  {
    key: 'media',
    bg: mediaSocialDesignImg,
    title: 'Media Social Design',
    subtitle: '媒體社群設計',
  },
  {
    key: 'brand',
    bg: brandDevelopmentImg,
    title: 'Brand Development',
    subtitle: '品牌發展',
  },
  {
    key: 'photo',
    bg: photographyImg,
    title: 'Photography',
    subtitle: '攝影',
  },
];

const HorizontalScrollServices: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    const track = trackRef.current;
    if (!container || !track) return;

    // Set track width to fit all slides in a row
    const updateTrackWidth = () => {
      const slideEls = track.querySelectorAll<HTMLElement>('.hss-slide');
      let totalWidth = 0;
      slideEls.forEach((slide) => {
        totalWidth += slide.offsetWidth;
      });
      track.style.width = `${totalWidth}px`;
    };
    updateTrackWidth();
    window.addEventListener('resize', updateTrackWidth);

    // Use gsap.context for safe animation and cleanup
    const ctx = gsap.context(() => {
      gsap.to(track, {
        x: () => {
          const maxScroll = track.scrollWidth - container.offsetWidth;
          return -maxScroll;
        },
        ease: 'none',
        scrollTrigger: {
          trigger: container,
          start: 'top top',
          end: () => `+=${track.scrollWidth - container.offsetWidth}`,
          pin: true,
          pinSpacing: true,
          scrub: 1.5,
          anticipatePin: 1,
          invalidateOnRefresh: true,
        },
      });
    }, container);

    return () => {
      window.removeEventListener('resize', updateTrackWidth);
      ctx.revert();
    };
  }, []);

  return (
    <>
      <div className="hss-section-title">
        <div className="hss-title-row">
          <span className="hss-title-en">How Can We Help?</span>
          <span className="hss-title-divider">|</span>
          <span className="hss-title-zh">我們如何幫助您？</span>
        </div>
        <div className="hss-title-row hss-title-row-sub">
          <span className="hss-title-en">Our Services</span>
          <span className="hss-title-divider">|</span>
          <span className="hss-title-zh">我們的服務</span>
        </div>
      </div>
      <section className="horizontal-scroll-services" ref={containerRef}>
        <div className="hss-track" ref={trackRef}>
          {slides.map((service) => (
            <div
              className="hss-slide"
              key={service.key}
            >
              <div
                className="hss-card"
                style={{ backgroundImage: `url(${service.bg})` }}
              >
                <div className="hss-overlay">
                  <h2 className="hss-title">{service.title}</h2>
                  <div className="hss-subtitle">{service.subtitle}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>
    </>
  );
};

export default HorizontalScrollServices;
