import { useState, useEffect } from 'react';
import './App.css';
import Navigation from './Components/Navigation';

import INTRO from './Components/Intro';
import HorizontalScrollServices from './Components/HorizontalScrollServices';
import VisionHelp from './Components/VisionHelp';
import Portfolio from './Components/Portfolio';
import Footer from './Components/Footer';

function App() {
  const [loading, setLoading] = useState(true);
  const [fadeOut, setFadeOut] = useState(false);

  useEffect(() => {
    // Moderated timing: start fade slightly earlier and remove sooner for snappier feel
    // Previous: fade @2500ms, remove @3500ms. New: fade @1600ms, remove @2400ms.
    const fadeTimer = setTimeout(() => {
      setFadeOut(true);
    }, 1600);

    const removeTimer = setTimeout(() => {
      setLoading(false);
    }, 2400); // 1.6s static + ~0.7s fade (transition) ≈ 2.3-2.4s total

    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(removeTimer);
    };
  }, []);

  if (loading) {
    return (
      <div className={`loading-container ${fadeOut ? 'fade-out' : ''}`}>
        <div className="spinner"></div>
        <p className="loading-text" data-text="IMAGINATING...">IMAGINATING...</p>
      </div>
    );
  }

  return (
    <div className="App">
      <Navigation />
      <div id="intro">
        <INTRO />
      </div>
      <HorizontalScrollServices />
      <Portfolio />
      <VisionHelp />
      <Footer />
    </div>
  );
}

export default App;
