import './Portfolio.css';
import { useScrollAnimation } from '../hooks/useScrollAnimation';
import { useRef, useCallback } from 'react';
import carousel1 from '../assets/carousel1.png';
import carousel2 from '../assets/carousel2.png';
import carousel3 from '../assets/carousel3.png';
import carousel4 from '../assets/carousel4.png';
import carousel5 from '../assets/carousel5.png';
import carousel6 from '../assets/carousel6.png';
import group4 from '../assets/Group 4 (1).png';
import p1 from '../assets/p1.png';
import p2 from '../assets/p2.png';
import p3 from '../assets/p3.png';
import laptop from '../assets/laptop.png';
import Carousel from './Carousel';

export default function Portfolio() {
  const { ref, isVisible } = useScrollAnimation(0.2);
  const photoRef = useRef<HTMLDivElement | null>(null);

  const onPhotoMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    const el = photoRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width; // 0..1
    const y = (e.clientY - rect.top) / rect.height; // 0..1
    el.style.setProperty('--mx', x.toString());
    el.style.setProperty('--my', y.toString());
  }, []);

  const onPhotoLeave = useCallback(() => {
    const el = photoRef.current;
    if (!el) return;
    el.style.setProperty('--mx', '0.5');
    el.style.setProperty('--my', '0.5');
  }, []);

  return (
    <section 
      id="portfolio" 
      className="portfolio-section"
      ref={ref as React.RefObject<HTMLElement>}
    >
      <div className={`portfolio-container ${isVisible ? 'animate' : ''}`}>
        <h2 className="portfolio-title">Portfolio</h2>
        <p className="portfolio-subtitle">作品集</p>
        
        <Carousel
          images={[
            { src: carousel1, alt: 'Portfolio Item 1' },
            { src: carousel2, alt: 'Portfolio Item 2' },
            { src: carousel3, alt: 'Portfolio Item 3' },
            { src: carousel4, alt: 'Portfolio Item 4' },
            { src: carousel5, alt: 'Portfolio Item 5' },
            { src: carousel6, alt: 'Portfolio Item 6' },
          ]}
          className="portfolio-carousel"
          autoplay
          intervalMs={6500}
          loop={true}
        />

        {/* Photography Full-Width Section */}
        <div
          className="photography-full-section"
          ref={photoRef}
          onMouseMove={onPhotoMove}
          onMouseLeave={onPhotoLeave}
        >
          <div className="photography-text-background">
            <div className="horizontal-text">PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY</div>
            <div className="horizontal-text">PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY</div>
            <div className="horizontal-text">PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY</div>
            <div className="horizontal-text">PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY</div>
            <div className="horizontal-text">PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY PHOTOGRAPHY</div>
          </div>
          <img src={group4} alt="Photography" className="photography-image" />
        </div>

        {/* Device Showcase Section */}
        <section className="device-showcase" aria-label="Device mockups">
          <div className="device-stage">
            <img src={laptop} alt="Laptop mockup" className="device-laptop" />
            <div className="device-row">
              <img src={p1} alt="Phone mockup 1" className="device-phone device-phone-1" />
              <img src={p2} alt="Phone mockup 2" className="device-phone device-phone-2" />
              <img src={p3} alt="Phone mockup 3" className="device-phone device-phone-3" />
            </div>
          </div>
        </section>
      </div>
    </section>
  );
}
