
import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { EffectCoverflow, Autoplay } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/effect-coverflow';
import './Carousel.css';


export type CarouselImage = {
  src: string;
  alt: string;
  kind?: 'default' | 'kanvasa';
};

type CarouselProps = {
  images: CarouselImage[];
  className?: string;
  autoplay?: boolean;
  intervalMs?: number;
  loop?: boolean;
};

export default function Carousel({
  images,
  className,
  autoplay = false,
  intervalMs = 3500,
  loop = true,
}: CarouselProps) {
  return (
    <Swiper
      className={className + ' swiper-coverflow'}
      modules={[EffectCoverflow, Autoplay]}
      effect="coverflow"
      grabCursor={true}
      centeredSlides={true}
      slidesPerView={"auto"}
      loop={loop}
      coverflowEffect={{
        rotate: 0,
        stretch: 0,
        depth: 120,
        modifier: 1.2,
        scale: 0.88,
        slideShadows: false,
      }}
      autoplay={autoplay ? { delay: intervalMs, disableOnInteraction: false } : false}
    >
      {images.map((img, i) => (
        <SwiperSlide key={i} style={{ width: '50vw', maxWidth: 420, minWidth: 180 }}>
          <img src={img.src} alt={img.alt} style={{ width: '100%', height: 'auto', borderRadius: 18 }} />
        </SwiperSlide>
      ))}
    </Swiper>
  );
}
